const body = $input.first().json.body || $input.first().json;
const data = body.data || body;
const instancia = body.instance || (data && data.instanceId) || '';
const key = (data && data.key) || {};
const fromMe = !!key.fromMe;
const remoteJid = key.remoteJid || '';
const numero = remoteJid.replace('@s.whatsapp.net', '').replace(/\D/g, '');
const msg = (data && data.message) || {};
const texto = msg.conversation || (msg.extendedTextMessage && msg.extendedTextMessage.text) || '';
const valido = !fromMe && !!texto && !!numero;
return [{ json: { valido, numero, texto, instancia } }];

const agentOutput = $input.first().json;
const texto = agentOutput.output || agentOutput.text || 'Desculpa, nao consegui processar isso agora.';
const numero = $('Extrair Mensagem Recebida').first().json.numero;
return [{ json: { numero, texto } }];
